<?php use App\UI\UI as U; $s=$data['sample']; ?>
<?= U::heading('Hours and availability','Set station hours and planned closures.',U::badge('Open until 6:00 PM','green')) ?>
<div class="grid gap-5 xl:grid-cols-2"><form class="panel space-y-4 p-4 md:p-5" data-local-form data-persist="station-weekly-hours" data-success="Weekly hours saved in this browser."><?= U::title('Weekly hours','clock') ?><div class="overflow-x-auto"><table class="data-table"><thead><tr><th>Day</th><th>Open time</th><th>Close time</th><th>Status</th></tr></thead><tbody><?php foreach($s['days'] as $i=>$day): ?><tr><td class="font-semibold"><?= U::e($day) ?></td><td><?= U::field($day.' opening time','open_'.$i,'07:00','time',['required'=>true,'label_class'=>'sr-only','class'=>'min-h-10 py-2']) ?></td><td><?= U::field($day.' closing time','close_'.$i,'18:00','time',['required'=>true,'label_class'=>'sr-only','class'=>'min-h-10 py-2']) ?></td><td><?= U::select($day.' status','status_'.$i,['open'=>'Open','closed'=>'Closed'],$i===6?'closed':'open',['label_class'=>'sr-only','class'=>'min-h-10 py-2']) ?></td></tr><?php endforeach ?></tbody></table></div><?= U::field('Same-day order cutoff','cutoff','17:00','time',['icon'=>'clock','required'=>true]) ?><p class="flex items-start gap-2 rounded-lg bg-amber-50 p-3 text-sm text-amber-800"><?= U::icon('alert','size-4 shrink-0') ?>Existing orders should be reviewed when operating hours change.</p><?= U::btn('Save weekly hours','','primary','check',['type'=>'submit']) ?></form>
<div class="space-y-5"><form class="panel space-y-4 p-4 md:p-5" data-local-form data-persist="station-closure" data-success="Closure draft saved in this browser. Customers have not been notified."><?= U::title('Temporary closure','alert') ?><?= U::select('Reason','reason',['maintenance'=>'Maintenance','no-operations'=>'No operations','other'=>'Other'],'maintenance') ?><div class="grid gap-4 sm:grid-cols-2"><?= U::field('Starts','starts','2026-11-04T13:00','datetime-local',['required'=>true]) ?><?= U::field('Ends','ends','2026-11-04T16:00','datetime-local',['required'=>true]) ?></div><?= U::textarea('Public notice','notice','Equipment maintenance. We reopen at 4:00 PM.',['required'=>true,'maxlength'=>200]) ?><label class="flex items-center gap-3 text-sm"><input type="checkbox" name="show_notice" checked class="size-5 accent-water">Show notice to customers during this closure</label><?= U::btn('Save closure','','primary','calendar',['type'=>'submit']) ?><div class="border-t border-line pt-4"><?= U::btn('Set no operations today','','secondary','alert',['data-dialog-open'=>'no-operations']) ?></div></form><section class="panel p-4 md:p-5"><?= U::title('Upcoming closures','calendar','mb-3') ?><?= U::table(['Date','Type','Details'],[['Nov 4, 2026','Maintenance','1:00 PM – 4:00 PM'],['Nov 8, 2026','No operations','All day']]) ?></section></div></div>
<dialog id="no-operations" class="w-full max-w-lg rounded-xl border border-line p-6 text-ink"><form data-local-form data-persist="station-no-operations" data-success="No-operations notice saved in this browser only." class="space-y-4"><?= U::title('No operations today','file','') ?><p class="muted">November 2, 2026. Review existing orders before contacting customers.</p><?= U::textarea('Customer notice','notice','No operations today. Please choose our next open day.',['id'=>'no-operations-notice','required'=>true,'maxlength'=>200]) ?><?= U::btn('Save local notice','','primary','check',['type'=>'submit']) ?><?= U::btn('Close','','secondary','close',['data-dialog-close'=>true]) ?></form></dialog>
